   */
  batchUpdatePermissionControl: (configs: UpdatePermissionControlParams[]) => {
    return request.post("/system/permission-control/batch-update", { configs });
  },

  /**
   * 获取系统配置
   */
  getSystemConfig: (key: string): Promise<SystemConfig> => {
